def compute(vars):
    denominator = vars["v3"]
    if denominator == 0:
        return None

    value = vars["v1"] / denominator

    return {
        "value": value,
        "trace": {
            "v1": vars["v1"],
            "v3": vars["v3"],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
